INSERT INTO growth_sources(title,text,url,author,kind,hypothesis,confirmed,permission) VALUES
 ('Переход: спрашивают детали, а не ставят лайки','Наблюдение 29.10.2026: у поста keyCRM о переносе данных 2 лайка и 13 ответов. Несколько участников просят детали перехода. Это признак интереса, не доказанные регистрации или оплаты. Использовать как исследование препятствий перехода; не приписывать Mimiao миграцию в один клик.','https://www.threads.com/@keycrmapp/post/DewLYRtkTEU','keycrmapp','public','transition',true,false),
 ('Школы выбирают между внутренним учётом и продажами','В обсуждении 09.04.2026 владелец школы сравнивает CRM. Участники обсуждают внутренний учёт, продажи, сочетание двух систем и собственные инструменты. Источник формулировок покупателя, не свежая заявка и не актуальная таблица возможностей конкурентов.','https://www.threads.com/@eliz_ukr/post/DW50hsPCMBF','eliz_ukr','public','accounting',true,false),
 ('Рекомендация Mimiao: система и поддержка','Публичная рекомендация Mimiao от @ler_dre_, которую владелец Mimiao подтвердил как платящего клиента. Автор исходной ветки ответила, что посмотрит продукт. Оплата или регистрация этой заинтересованной школы не подтверждена. Для отдельного клиентского кейса ещё нужно согласие.','https://www.threads.com/@ler_dre_/post/DfCX1ZiAIK1','ler_dre_','customer','transition',true,false),
 ('Основатель помогает новым школам','Владелец Mimiao подтвердил 29.10.2026: помогает всем новым школам, времени хватает. Можно предложить личную помощь с первым рабочим сценарием в переписке. Это не обещание перенести всю историю, разработать любые функции или выдержать непроверенный срок.',NULL,'Илля','founder','transition',true,false);
